(i=>{var t=i(".site-title");wp.customize("blogname",function(n){n.bind(function(n){0==t.find("img").length&&t.children("a").text(n)})}),wp.customize("blogdescription",function(n){n.bind(function(n){var t=i(".tagline");0==t.length&&i("#title-container").append('<p class="tagline"></p>'),t.text(n)})})})(jQuery);